import { test, expect } from '@playwright/test';

test.describe('Table Row Numbering', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display row numbers in the first column of a table', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify row number column header exists
    const rowNumberHeader = page.getByRole('columnheader', { name: /row number/i });
    await expect(rowNumberHeader).toBeVisible();

    // Verify row number column has at least 1 row
    const rowNumberColumn = page.locator('[data-testid="row-number-column"]');
    const rowCount = await rowNumberColumn.locator('tr').count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify row numbers are displayed
    const firstRowNumber = page.locator('[data-testid="row-number-cell"]').first();
    const firstRowNumberText = await firstRowNumber.textContent();
    expect(firstRowNumberText).toContain('1');

    const lastRowNumber = page.locator('[data-testid="row-number-cell"]').last();
    const lastRowNumberText = await lastRowNumber.textContent();
    expect(lastRowNumberText).toContain(String(rowCount);
  });

  test('should handle edge case with empty table and not display row numbers', async ({ page }) => {
    // Navigate to empty table view
    await page.goto('/table-list/empty');

    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify no row number column header exists
    const rowNumberHeader = page.getByRole('columnheader', { name: /row number/i });
    await expect(rowNumberHeader).not.toBeVisible();

    // Verify no row number cells exist
    const rowNumberCells = page.locator('[data-testid="row-number-cell"]');
    const cellCount = await rowNumberCells.count();
    expect(cellCount).toBe(0);

    // Verify empty state message is displayed
    const emptyMessage = page.getByText(/no data available/i);
    await expect(emptyMessage).toBeVisible();
  });
});
